using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using TextAnalysis;

const string SampleText =
    "The quick brown fox jumps over the lazy dog " +
    "A stitch in time saves nine " +
    "To be or not to be that is the question " +
    "All that glitters is not gold " +
    "Actions speak louder than words " +
    "Knowledge is power and power is knowledge " +
    "The early bird catches the worm " +
    "Better late than never but never late is better " +
    "Practice makes perfect so keep practicing every single day";

var analyzer = new TextAnalyzer(SampleText);

// Warmup
for (int i = 0; i < 100_000; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

string runtime = RuntimeInformation.FrameworkDescription;
Console.WriteLine($"Runtime: {runtime}");
Console.WriteLine($"{"Method",-25} {"Mean (ns)",15} {"Iterations",12}");
Console.WriteLine(new string('-', 55));

Bench("AverageWordLength", () => analyzer.AverageWordLength());
Bench("WordLengthHistogram", () => analyzer.WordLengthHistogram());
Bench("UniqueWordCount", () => analyzer.UniqueWordCount());

[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Action action)
{
    // Run for ~2 seconds to get stable numbers
    const long targetMs = 2000;
    long iterations = 0;
    var sw = Stopwatch.StartNew();
    while (sw.ElapsedMilliseconds < targetMs)
    {
        for (int i = 0; i < 1000; i++)
            action();
        iterations += 1000;
    }
    sw.Stop();
    double meanNs = (double)sw.Elapsed.TotalNanoseconds / iterations;
    Console.WriteLine($"{name,-25} {meanNs,15:F2} {iterations,12}");
}

